/**
 * How-to記事データ
 * SEOロングテール拡大のためのコンテンツ記事
 */

export interface AmazonLink {
  keyword: string;
  label: string;
}

export interface HowtoArticle {
  slug: string;
  title: string;
  description: string;
  /** SEO用 <title>タグ（60文字以内、主要KWを前方配置） */
  metaTitle?: string;
  /** SEO用 meta description（120〜160文字、主要KW含む） */
  metaDescription?: string;
  icon: string;
  publishedAt: string;
  /** 最終更新日（E-E-A-T: 鮮度シグナル） */
  updatedAt: string;
  /** 記事冒頭の「この記事のポイント」3〜4行 */
  summaryPoints: string[];
  keywords: string[];
  sections: ArticleSection[];
  faq: { q: string; a: string }[];
  relatedTemplates: string[]; // template IDs
  /** CTA用の推奨テンプレートID（シミュレーターにこのテンプレートを適用して遷移） */
  primaryTemplate: string;
  /** CTA用の推奨テンプレート説明（例: "漫画200冊収納の本棚" ） */
  primaryCta: string;
  /** 記事に関連する材料・工具のAmazonリンク */
  amazonLinks?: AmazonLink[];
}

export interface ArticleSection {
  heading: string;
  paragraphs: string[];
  list?: string[];
  tip?: string;
}

